# =============================================================================
# 05-expand-ui-components.ps1
# Saachi AI - Step 05: Expand shared UI component library (packages/ui)
# Adds: Input, Textarea, Select, Checkbox, Skeleton, EmptyState, Modal
# Files are embedded as Base64 to avoid PowerShell here-string parsing issues.
# All paths are resolved to absolute paths before writing (fixes .NET
# CurrentDirectory vs PowerShell $PWD mismatch on paths with spaces).
# Run from the repo root.
# =============================================================================

$ErrorActionPreference = "Stop"

# Resolve repo root as an ABSOLUTE path (fixes WriteAllBytes DirectoryNotFoundException)
$RepoRoot = (Get-Location).Path
$uiComponentsDir = Join-Path $RepoRoot "packages\ui\src\components"
$uiSrcDir = Join-Path $RepoRoot "packages\ui\src"

if (-not (Test-Path $uiComponentsDir)) {
    Write-Error "Could not find $uiComponentsDir -- run this script from the repo root (where package.json / turbo.json live)."
    exit 1
}

Write-Host "Repo root resolved to: $RepoRoot" -ForegroundColor DarkGray
Write-Host "Creating UI components in $uiComponentsDir ..." -ForegroundColor Cyan

function Write-Base64File {
    param(
        [string]$Path,
        [string]$Base64Content
    )
    $bytes = [System.Convert]::FromBase64String($Base64Content)
    $dir = Split-Path -Parent $Path
    if (-not (Test-Path $dir)) {
        New-Item -ItemType Directory -Path $dir -Force | Out-Null
    }
    [System.IO.File]::WriteAllBytes($Path, $bytes)
    Write-Host "  wrote $Path"
}

$b64_Input_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Input.tsx") -Base64Content $b64_Input_tsx

$b64_Textarea_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Textarea.tsx") -Base64Content $b64_Textarea_tsx

$b64_Select_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Select.tsx") -Base64Content $b64_Select_tsx

$b64_Checkbox_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Checkbox.tsx") -Base64Content $b64_Checkbox_tsx

$b64_Skeleton_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Skeleton.tsx") -Base64Content $b64_Skeleton_tsx

$b64_EmptyState_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "EmptyState.tsx") -Base64Content $b64_EmptyState_tsx

$b64_Modal_tsx = ""
Write-Base64File -Path (Join-Path $uiComponentsDir "Modal.tsx") -Base64Content $b64_Modal_tsx

$b64_index_ts = ""
Write-Base64File -Path (Join-Path $uiSrcDir "index.ts") -Base64Content $b64_index_ts

Write-Host ""
Write-Host "Done. New components created:" -ForegroundColor Green
Write-Host "  - packages/ui/src/components/Input.tsx"
Write-Host "  - packages/ui/src/components/Textarea.tsx"
Write-Host "  - packages/ui/src/components/Select.tsx"
Write-Host "  - packages/ui/src/components/Checkbox.tsx"
Write-Host "  - packages/ui/src/components/Skeleton.tsx"
Write-Host "  - packages/ui/src/components/EmptyState.tsx"
Write-Host "  - packages/ui/src/index.ts (updated exports)"
Write-Host ""
Write-Host "Next: run: pnpm type-check --filter=@saachi/ui" -ForegroundColor Yellow